package com.rockproject.mt6789

import com.rockproject.mt6789.data.BootApplyManager
import org.junit.Assert.*
import org.junit.Test
import java.io.File

class BootScriptRenderingTest {

    private val sampleTemplate = """
#!/system/bin/sh
# Rock Project - apply on boot. GENERATED BY THE APP. Do not edit by hand.
BASE=/data/adb/mt6789
P=/sys/module/overclock_mt6789/parameters
LOG=${'$'}BASE/boot.log
RES=${'$'}BASE/boot_result.json

mkdir -p "${'$'}BASE"
if [ -f "${'$'}LOG" ] && [ "${'$'}(wc -c < "${'$'}LOG")" -gt 65536 ]; then : > "${'$'}LOG"; fi
log() { echo "${'$'}(date '+%F %T') ${'$'}*" >> "${'$'}LOG"; }
finish() {   # ${'$'}1 = ok|fail   ${'$'}2 = message
  printf '{"time":%s,"status":"%s","message":"%s"}\n' "${'$'}(date +%s)" "${'$'}1" "${'$'}2" > "${'$'}RES"
  log "${'$'}1: ${'$'}2"
}
w() { echo "${'$'}2" > "${'$'}P/${'$'}1" 2>>"${'$'}LOG" || log "write failed: ${'$'}1=${'$'}2"; }

# 1) wait until Android finished booting (max 180 s)
i=0
until [ "${'$'}(getprop sys.boot_completed)" = "1" ]; do
  i=${'$'}((i+1))
  if [ "${'$'}i" -gt 180 ]; then finish fail "boot_completed timeout"; exit 1; fi
  sleep 1
done

# 2) wait for the kernel module parameters (max 60 s)
i=0
until [ -d "${'$'}P" ]; do
  i=${'$'}((i+1))
  if [ "${'$'}i" -gt 60 ]; then finish fail "overclock_mt6789 not loaded"; exit 2; fi
  sleep 1
done
sleep 3   # let thermal / EEM / vendor init settle

# 3) CPU overclock
@CPU_OC_BLOCK@

# 4) GPU overclock
@GPU_OC_BLOCK@

# 5) Control screen values
@CONTROLS_BLOCK@

if [ "${'$'}cpu_ok" -eq 1 ] && [ "${'$'}gpu_ok" -eq 1 ]; then
  finish ok "applied"
else
  finish fail "cpu=${'$'}cpu_ok gpu=${'$'}gpu_ok (see boot.log)"
fi
    """.trimIndent()

    @Test
    fun `test boot script rendering with oc active`() {
        val script = BootApplyManager.renderScript(
            templateContent = sampleTemplate,
            isCpuOc = true,
            cpuLLKhz = 2100000L,
            cpuBKhz = 2300000L,
            isGpuOc = true,
            gpuFreqParam = "gpu_target_khz",
            gpuFreqKhz = 1200000L,
            gpuVoltRaw = 80000L,
            controlCommands = listOf("echo schedutil > /sys/devices/system/cpu/cpufreq/policy0/scaling_governor 2>>\"\$LOG\"")
        )

        // Must contain $(getprop sys.boot_completed) with NO backslash
        assertTrue(script.contains("until [ \"\$(getprop sys.boot_completed)\" = \"1\" ]; do"))
        assertFalse(script.contains("\\$(getprop"))

        // Must contain NO unreplaced tokens
        assertFalse(script.contains("@CPU_OC_BLOCK@"))
        assertFalse(script.contains("@GPU_OC_BLOCK@"))
        assertFalse(script.contains("@CONTROLS_BLOCK@"))
        assertFalse(script.contains("@"))

        // Must contain timeouts
        assertTrue(script.contains("boot_completed timeout"))
        assertTrue(script.contains("overclock_mt6789 not loaded"))

        // Must contain 3-attempt loop and OC targets
        assertTrue(script.contains("cpu_ll_target_khz 2100000"))
        assertTrue(script.contains("cpu_b_target_khz 2300000"))
        assertTrue(script.contains("gpu_target_khz 1200000"))
        assertTrue(script.contains("gpu_target_volt 80000"))
        assertTrue(script.contains("gpu_target_vsram 80000"))

        // Must contain control command
        assertTrue(script.contains("echo schedutil > /sys/devices/system/cpu/cpufreq/policy0/scaling_governor"))
    }

    @Test
    fun `test boot script rendering with stock targets`() {
        val script = BootApplyManager.renderScript(
            templateContent = sampleTemplate,
            isCpuOc = false,
            cpuLLKhz = 2000000L,
            cpuBKhz = 2200000L,
            isGpuOc = false,
            gpuFreqParam = "gpu_target_khz",
            gpuFreqKhz = 1000000L,
            gpuVoltRaw = 73500L,
            controlCommands = emptyList()
        )

        assertTrue(script.contains("cpu_ok=1"))
        assertTrue(script.contains("gpu_ok=1"))
        assertFalse(script.contains("@"))
        assertFalse(script.contains("\\$(getprop"))
    }

    @Test
    fun `test boot script rendering with prime oc active`() {
        val script = BootApplyManager.renderScript(
            templateContent = sampleTemplate,
            isCpuOc = true,
            cpuLLKhz = 2100000L,
            cpuBKhz = 2300000L,
            cpuPrimeKhz = 2500000L,
            isGpuOc = false,
            gpuFreqParam = "gpu_target_khz",
            gpuFreqKhz = 1000000L,
            gpuVoltRaw = 73500L,
            controlCommands = emptyList()
        )

        assertTrue(script.contains("if [ \"\$(cat \"\$P/cpu_prime_status\" 2>/dev/null)\" = \"active\" ]; then"))
        assertTrue(script.contains("w cpu_prime_target_khz 2500000"))
    }
}
